package kfc.utils;
import javax.swing.table.TableModel;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import java.awt.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
/** XLSX OOXML tối giản, PDF nhiều trang dạng ảnh Unicode, không cần thư viện ngoài. */
public final class ReportExport {
 private static String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","");}
 private static void entry(ZipOutputStream z,String name,String text)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(text.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 public static void xlsx(TableModel m,File file)throws IOException{try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(file))){entry(z,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");entry(z,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Bao cao\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");entry(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");StringBuilder s=new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>");for(int r=-1;r<m.getRowCount();r++){s.append("<row>");for(int c=0;c<m.getColumnCount();c++){Object v=r<0?m.getColumnName(c):m.getValueAt(r,c);if(v instanceof Number)s.append("<c><v>").append(v).append("</v></c>");else s.append("<c t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(v==null?"":v.toString())).append("</t></is></c>");}s.append("</row>");}s.append("</sheetData></worksheet>");entry(z,"xl/worksheets/sheet1.xml",s.toString());}}
 private static void bytes(ByteArrayOutputStream out,String s)throws IOException{out.write(s.getBytes(StandardCharsets.US_ASCII));}
 public static void pdf(TableModel m,File file)throws IOException{int pageSize=30,pages=Math.max(1,(m.getRowCount()+pageSize-1)/pageSize);ByteArrayOutputStream out=new ByteArrayOutputStream();ArrayList<Integer> offsets=new ArrayList<>();offsets.add(0);bytes(out,"%PDF-1.4\n");StringBuilder kids=new StringBuilder();for(int i=0;i<pages;i++)kids.append(3+i*3).append(" 0 R ");obj(out,offsets,1,"<< /Type /Catalog /Pages 2 0 R >>");obj(out,offsets,2,"<< /Type /Pages /Count "+pages+" /Kids ["+kids+"] >>");for(int i=0;i<pages;i++){int id=3+i*3;BufferedImage im=new BufferedImage(1400,1000,BufferedImage.TYPE_INT_RGB);Graphics2D g=im.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,1400,1000);g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);g.setColor(new Color(180,0,40));g.setFont(new Font("SansSerif",Font.BOLD,30));g.drawString("KFC - Báo cáo doanh thu",45,55);g.setFont(new Font("SansSerif",Font.PLAIN,20));g.setColor(Color.DARK_GRAY);g.drawString("Trang "+(i+1)+"/"+pages,45,85);int cw=1310/Math.max(1,m.getColumnCount());for(int r=-1;r<pageSize;r++){int row=i*pageSize+r;if(r>=0&&row>=m.getRowCount())break;int y=120+(r+1)*27;g.setColor(r==-1?new Color(225,228,233):r%2==0?new Color(246,247,248):Color.WHITE);g.fillRect(45,y-22,1310,27);g.setColor(Color.BLACK);for(int c=0;c<m.getColumnCount();c++){Object v=r==-1?m.getColumnName(c):m.getValueAt(row,c);String s=v==null?"":v.toString();while(s.length()>0&&g.getFontMetrics().stringWidth(s)>cw-12)s=s.substring(0,s.length()-1);g.drawString(s,51+c*cw,y);}}g.dispose();ByteArrayOutputStream image=new ByteArrayOutputStream();ImageIO.write(im,"jpg",image);obj(out,offsets,id,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im0 "+(id+1)+" 0 R >> >> /Contents "+(id+2)+" 0 R >>");stream(out,offsets,id+1,"/Type /XObject /Subtype /Image /Width 1400 /Height 1000 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode",image.toByteArray());stream(out,offsets,id+2,"","q 833 0 0 595 4 0 cm /Im0 Do Q".getBytes(StandardCharsets.US_ASCII));}int x=out.size();bytes(out,"xref\n0 "+offsets.size()+"\n0000000000 65535 f \n");for(int i=1;i<offsets.size();i++)bytes(out,String.format(Locale.ROOT,"%010d 00000 n \n",offsets.get(i)));bytes(out,"trailer\n<< /Size "+offsets.size()+" /Root 1 0 R >>\nstartxref\n"+x+"\n%%EOF\n");try(FileOutputStream f=new FileOutputStream(file)){out.writeTo(f);}}
 private static void obj(ByteArrayOutputStream o,ArrayList<Integer> offsets,int id,String s)throws IOException{offsets.add(o.size());bytes(o,id+" 0 obj\n"+s+"\nendobj\n");}
 private static void stream(ByteArrayOutputStream o,ArrayList<Integer> offsets,int id,String dict,byte[] b)throws IOException{offsets.add(o.size());bytes(o,id+" 0 obj\n<< "+dict+" /Length "+b.length+" >>\nstream\n");o.write(b);bytes(o,"\nendstream\nendobj\n");}
}
